begin;
select no_plan();
insert into auth.users(id,email) values('00000000-0000-4000-8000-000000002501','credits@test.local');
insert into public.families(id,name,created_by) values('10000000-0000-4000-8000-000000002501','Credits','00000000-0000-4000-8000-000000002501');
insert into public.family_members(family_id,user_id) values('10000000-0000-4000-8000-000000002501','00000000-0000-4000-8000-000000002501');
insert into public.learning_credit_grants(family_id,kind,amount,ends_at,reason) values('10000000-0000-4000-8000-000000002501','ai_questions',2,now()+interval '1 day','Contribution');
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is((public.get_prova_entitlement('10000000-0000-4000-8000-000000002501')->>'ai_generate_remaining')::int,2,'free family can use earned AI questions');
select ok(public.reserve_prova_generation_v2('20000000-0000-4000-8000-000000002501','10000000-0000-4000-8000-000000002501','00000000-0000-4000-8000-000000002501',repeat('a',64),1)?'lease','server reserves bonus with fenced lease');
select is((public.get_prova_entitlement('10000000-0000-4000-8000-000000002501')->>'ai_generate_remaining')::int,1,'reserved bonus unavailable to parallel calls');
select is(public.reserve_prova_generation_v2('20000000-0000-4000-8000-000000002501','10000000-0000-4000-8000-000000002501','00000000-0000-4000-8000-000000002501',repeat('a',64),1)->>'error','generation_in_progress','same ID cannot create parallel paid call');
select is(public.reserve_prova_generation_v2('20000000-0000-4000-8000-000000002501','10000000-0000-4000-8000-000000002501','00000000-0000-4000-8000-000000002501',repeat('a',64),2)->>'error','request_conflict','count is part of intent');
select throws_ok($$select public.save_prova_provider_result('20000000-0000-4000-8000-000000002501',gen_random_uuid(),'{}')$$,'P0001','lease_lost','late writer cannot persist result');
select lives_ok($$select public.save_prova_provider_result('20000000-0000-4000-8000-000000002501',(select lease from public.prova_generation_jobs where id='20000000-0000-4000-8000-000000002501'),'{"output":{"questions":[]}}')$$,'provider result durably saved before applying');
select ok(public.reserve_prova_generation_v2('20000000-0000-4000-8000-000000002501','10000000-0000-4000-8000-000000002501','00000000-0000-4000-8000-000000002501',repeat('a',64),1)?'provider_result','lost apply request resumes saved provider result');
select is(public.complete_prova_generation_v2('20000000-0000-4000-8000-000000002501',(select lease from public.prova_generation_jobs where id='20000000-0000-4000-8000-000000002501'),'[{"grade":5,"subject":"Fen","topic":"Isı","kind":"open_ended","difficulty":"orta","stem":"Isı nedir?","expected_answer":"Enerji aktarımı","solution":"Açıklama","source_urls":[],"provenance":{}}]','test','test',10,20)->>'remaining','1','completion consumes one bonus only');
select is((public.get_prova_entitlement('10000000-0000-4000-8000-000000002501')->>'ai_generate_remaining')::int,1,'bonus credit not also subtracted from base quota');
select ok(public.complete_prova_generation_v2('20000000-0000-4000-8000-000000002501',(select lease from public.prova_generation_jobs where id='20000000-0000-4000-8000-000000002501'),'[]','test','test',10,20)?'questions','completion replay returns original');
select is((select sum(consumed)::int from public.generation_credit_allocations),1,'completion replay charges once');
select is((select sum(items)::int from public.prova_ai_usage where family_id='10000000-0000-4000-8000-000000002501'),1,'usage once');
select ok(public.reserve_prova_generation_v2('20000000-0000-4000-8000-000000002502','10000000-0000-4000-8000-000000002501','00000000-0000-4000-8000-000000002501',repeat('b',64),1)?'lease','second job starts');
select lives_ok($$select public.fail_prova_generation_v2('20000000-0000-4000-8000-000000002502',(select lease from public.prova_generation_jobs where id='20000000-0000-4000-8000-000000002502'),'provider_outcome_unknown',true)$$,'uncertain result kept');
select is(public.reserve_prova_generation_v2('20000000-0000-4000-8000-000000002502','10000000-0000-4000-8000-000000002501','00000000-0000-4000-8000-000000002501',repeat('b',64),1)->>'error','ai_result_uncertain','uncertain result is not silently charged again');
select is((public.get_prova_entitlement('10000000-0000-4000-8000-000000002501')->>'ai_generate_remaining')::int,0,'uncertain charge stays reserved');
reset role;
select lives_ok($$delete from auth.users where id='00000000-0000-4000-8000-000000002501';set constraints all immediate;$$,'credit allocation does not block account deletion');
select * from finish();
rollback;
